//! #636 design A, fix-delta review of 33e23e42: W1-W7 and S1 rows. The Strong rows fail on 33e23e42.

use super::taint_sink_strength_test::*;

#[test]
fn python_fix_delta_round_3() {
    assert_severities(&[
        py("W1 self.m defined twice, second raw", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    def base_query(self, session, s):\n        return session.query(User)\n    def base_query(self, session, s):\n        return session.query(User).order_by(literal_column(s))\n    def h(self, session, req):\n        s = req.args['s']\n        x = req.args['x']  # SEED\n        return self.base_query(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("W1 method defined in a class-body if block", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    if True:\n        def base_query(self, session, s):\n            return session.query(User).order_by(literal_column(s))\n    def h(self, session, req):\n        s = req.args['s']\n        x = req.args['x']  # SEED\n        return self.base_query(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("W1 property and setter pair", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass R:\n    @property\n    def base_query(self):\n        return None\n    @base_query.setter\n    def base_query(self, v):\n        pass\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", W),
        py("W2 inherited from a same-file base, raw", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass B:\n    def base_query(self, session, s):\n        return session.query(User).order_by(literal_column(s))\nclass R(B):\n    def h(self, session, req):\n        s = req.args['s']\n        x = req.args['x']  # SEED\n        return self.base_query(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("W2 same-file subclass overrides with raw", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass B:\n    def base_query(self, session, s):\n        return session.query(User)\n    def h(self, session, req):\n        s = req.args['s']\n        x = req.args['x']  # SEED\n        return self.base_query(session, s).filter(User.id == x).all()  # SINK\nclass R(B):\n    def base_query(self, session, s):\n        return session.query(User).order_by(literal_column(s))\n", W),
        py("recall W2: inherited clean method from a same-file base", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass B:\n    def base_query(self, session):\n        return session.query(User).order_by(User.id)\nclass R(B):\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", S),
        py("recall W2: Django-style get_queryset defined in two unrelated classes", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nclass A:\n    def get_queryset(self, session):\n        return session.query(User).order_by(User.id)\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.get_queryset(session).filter(User.id == x).all()  # SINK\nclass B:\n    def get_queryset(self, session):\n        return session.query(User)\n", S),
        py("recall W2: method defined once, class with an unresolved base", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app.base import Base\nclass R(Base):\n    def base_query(self, session):\n        return session.query(User).order_by(User.id)\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", S),
        py("recall W1: method not defined in the class stays an opaque root", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app.base import Base\nclass R(Base):\n    def h(self, session, req):\n        x = req.args['x']  # SEED\n        return self.base_query(session).filter(User.id == x).all()  # SINK\n", S),
        py("W3 helper passes through a raw chain argument", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef scoped(q):\n    return q.filter(User.deleted == False)\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return scoped(session.query(User).order_by(literal_column(s))).filter(User.id == x).all()  # SINK\n", W),
        py("W3 helper passes through a local raw chain", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef scoped(q):\n    return q.filter(User.deleted == False)\ndef h(session, req):\n    s = req.args['s']\n    raw = session.query(User).order_by(literal_column(s))\n    x = req.args['x']  # SEED\n    return scoped(raw).filter(User.id == x).all()  # SINK\n", W),
        py("W3 raw chain as keyword argument", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef scoped(q=None):\n    return q.filter(User.deleted == False)\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return scoped(q=session.query(User).order_by(literal_column(s))).filter(User.id == x).all()  # SINK\n", W),
        py("recall W3: helper passes through a clean chain argument", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef scoped(q):\n    return q.filter(User.deleted == False)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return scoped(session.query(User).order_by(User.id)).filter(User.id == x).all()  # SINK\n", S),
        py("control W3: imported helper with a raw argument stays opaque (D1)", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app.q import scoped\ndef h(session, req):\n    s = req.args['s']\n    raw = session.query(User).order_by(literal_column(s))\n    x = req.args['x']  # SEED\n    return scoped(raw).filter(User.id == x).all()  # SINK\n", S),
        py("W4 module-level lambda helper, raw", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nbase = lambda session, s: session.query(User).order_by(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    x = req.args['x']  # SEED\n    return base(session, s).filter(User.id == x).all()  # SINK\n", W),
        py("W4 functools.partial of a raw def", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom functools import partial\ndef mk(session, s):\n    return session.query(User).order_by(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    base = partial(mk, session, s)\n    x = req.args['x']  # SEED\n    return base().filter(User.id == x).all()  # SINK\n", W),
        py("recall W4: module-level lambda helper, clean", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nbase = lambda session: session.query(User).order_by(User.id)\ndef h(session, req):\n    x = req.args['x']  # SEED\n    return base(session).filter(User.id == x).all()  # SINK\n", S),
        py("W5 setdefault result appended raw", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    d = {}\n    d.setdefault('k', []).append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(d['k']), User.id == x))  # SINK\n", W),
        py("W5 setdefault result aliased then appended", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    d = {}\n    lst = d.setdefault('k', [])\n    lst.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(d['k']), User.id == x))  # SINK\n", W),
        py("W6 loop target mutates a nested element", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [[]]\n    for v in vals:\n        v.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals[0]), User.id == x))  # SINK\n", W),
        py("W6 comprehension target mutates a nested element", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [[]]\n    [v.append(literal_column(s)) for v in vals]\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals[0]), User.id == x))  # SINK\n", W),
        py("W6 appended empty list mutated through the loop target", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = []\n    vals.append([])\n    for v in vals:\n        v.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals[0]), User.id == x))  # SINK\n", W),
        py("W6 reader copy exposes a nested element", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [[]]\n    list(vals)[0].append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals[0]), User.id == x))  # SINK\n", W),
        py("W7 binary + init, list.append", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [] + []\n    list.append(vals, literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("W7 conditional init, same-file helper appends", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef add(v, s):\n    v.append(literal_column(s))\ndef h(session, req):\n    s = req.args['s']\n    vals = [] if s else []\n    add(vals, s)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("W7 slice init, operator.setitem", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nimport operator\ndef h(session, req):\n    s = req.args['s']\n    vals = [1][:]\n    operator.setitem(vals, 0, literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("disclosed D1: getlist init with an alias append stays weak", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = req.args.getlist('ids')\n    v2 = vals\n    v2.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("disclosed D1: split init with an alias append stays weak", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = s.split(',')\n    v2 = vals\n    v2.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("S1 truthiness guard before in_", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = [r.id for r in req.rows]\n    if not vals:\n        return []\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("S1 if vals guard", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = []\n    for r in req.rows:\n        vals.append(r.id)\n    if vals:\n        pass\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("S1 membership test", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [1, 2]\n    if s in vals:\n        pass\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("S1 while and assert and conditional-expression tests", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    vals = [1, 2]\n    assert vals\n    n = 1 if vals else 2\n    while vals and n:\n        break\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", S),
        py("S1 sample: set comprehension, early return on empty", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app import db\nfrom app.models import Slice\ndef f(chart_ids, req):\n    x = req.args.get('x')  # SEED\n    ids: set[int] = {cid for cid in chart_ids if cid}\n    if not ids:\n        return set()\n    return db.session.query(Slice.id).filter(Slice.id.in_(ids), Slice.k == x).all()  # SINK\n", S),
        py("S1 sample: conditional expression on the container", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\nfrom app.models import SemanticView\ndef g(session, m, req):\n    x = req.args.get('x')  # SEED\n    requested_ids = {t for ids in m.values() for t in ids if t is not None}\n    existing = set(session.scalars(select(SemanticView.id).where(SemanticView.id.in_(requested_ids), SemanticView.k == x))) if requested_ids else set()  # SINK\n    return existing\n", S),
        py("S1 value use through or aliases and stays strong", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef h(session, req):\n    s = req.args['s']\n    vals = [1, 2]\n    y = vals or []\n    y.append(literal_column(s))\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
        py("S1 value use as a return operand stays strong", "from sqlalchemy import select, func, literal_column, text\nfrom app.models import User\ndef k(vals):\n    return vals\ndef h(session, req):\n    vals = [1, 2]\n    y = k(vals or None)\n    x = req.args['x']  # SEED\n    session.execute(select(User).where(User.a.in_(vals), User.id == x))  # SINK\n", W),
    ]);
}
